arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" --data-urlencode "types=public_channel,private_channel" --data-urlencode "limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR', d); sys.exit(1)
for c in d['channels']:
    if c['name'] in ('incidents','payments-oncall'):
        print(c['id'], c['name'])
"

